  const moire=Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx*0.15+sy*0.15)+t*0.4)*0.5;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+reaction2+moire*0.15)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.65+cell*0.2+reaction2*0.15,v=blend*0.5+0.5;
  const pal=[[5,12,55],[12,55,95],[18,110,130],[30,160,140],[120,190,100],[210,190,60],[220,140,55],[200,80,60],[160,45,70],[90,25,60],[40,15,55],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
